const SUBSCRIPTION_PRICING = {
  premium: 9.99,
  enterprise: 49.99
} as const;

const PRICING_CONFIG = {
  TAX_RATE: 0.08,
  PROCESSING_FEE_RATE: 0.029
} as const;

function calculateSubscriptionPrice(tier: 'premium' | 'enterprise'): number {
  const basePrice = SUBSCRIPTION_PRICING[tier];
  return applyFeesAndTaxes(basePrice, PRICING_CONFIG);
}

function applyFeesAndTaxes(basePrice: number, config: typeof PRICING_CONFIG): number {
  const tax = basePrice * config.TAX_RATE;
  const fee = basePrice * config.PROCESSING_FEE_RATE;
  return basePrice + tax + fee;
}

